index bb8674982..4bc68ca4c 100644
--- a/src/main/java/io/reactivex/rxjava4/internal/schedulers/InstantPeriodicTask.java
+++ b/src/main/java/io/reactivex/rxjava4/internal/schedulers/InstantPeriodicTask.java
@@ -63,11 +63,12 @@ final class InstantPeriodicTask implements Callable<Void>, Disposable {

     @Override
     public void dispose() {
-        Future<?> current = first.getAndSet(CANCELLED);
-        if (current != null && current != CANCELLED) {
-            current.cancel(runner != Thread.currentThread());
-        }
-        current = rest.getAndSet(CANCELLED);
+        disposeFuture(first);
+        disposeFuture(rest);
+    }
+
+    private void disposeFuture(AtomicReference<Future<?>> ref) {
+        Future<?> current = ref.getAndSet(CANCELLED);
         if (current != null && current != CANCELLED) {
             current.cancel(runner != Thread.currentThread());
         }
@@ -79,26 +80,21 @@ final class InstantPeriodicTask implements Callable<Void>, Disposable {
     }

     void setFirst(Future<?> f) {
-        for (;;) {
-            Future<?> current = first.get();
-            if (current == CANCELLED) {
-                f.cancel(runner != Thread.currentThread());
-                return;
-            }
-            if (first.compareAndSet(current, f)) {
-                return;
-            }
-        }
+        setFuture(first, f);
     }

     void setRest(Future<?> f) {
+        setFuture(rest, f);
+    }
+
+    private void setFuture(AtomicReference<Future<?>> ref, Future<?> f) {
         for (;;) {
-            Future<?> current = rest.get();
+            Future<?> current = ref.get();
             if (current == CANCELLED) {
                 f.cancel(runner != Thread.currentThread());
                 return;
             }
-            if (rest.compareAndSet(current, f)) {
+            if (ref.compareAndSet(current, f)) {
                 return;
             }
         }
